from typing import Iterable, List


def f(values: Iterable[int]) -> List[int]:
    """偶数の要素だけを2乗して、元の順序のままリストで返す。"""
    result = []
    for value in values:
        if value % 2 == 0:
            result.append(value * value)
    return result

def square_evens(numbers):
    """偶数を2乗したリストを返す。"""
    return sorted({n * n for n in numbers if n % 2 == 0})


